def two_moduli(label,left,right,key,kp,instruction=None):
 p=equation(label,f'Abs({left})-Abs({right})',key,kp)
 p.setdefault('additional_operations',{})['two-sign-branches']={'kind':'identity','operands':[f'FiniteSet(*solve(({left})-({right}),x),*solve(({left})+({right}),x))']}
 p.setdefault('additional_operation_expected',{})['two-sign-branches']=key
 p['additional_operations']['squared-equality']={'kind':'identity','operands':[f'solveset(expand(({left})**2-({right})**2),x,domain=S.Reals)']};p['additional_operation_expected']['squared-equality']=key
 p.update(valid_alternative_methods=['Two sign branches:left=right or left=−right','Square both already nonnegative moduli,then solve the difference of squares'],source_method_instruction=instruction or'The worked example demonstrates BOTH methods.')
 return p
